with a as( select DISTINCT aa.finish_main_id ,aa.should_inspect_num from ${inspectFinishDispatcherTable} aa where aa.delete_flag = false GROUP BY aa.finish_main_id ,aa.should_inspect_num ) , b as( select a.finish_main_id,sum(a.should_inspect_num) as should_inspect_num from a GROUP BY a.finish_main_id ), c as( select cc.finish_main_id, sum(cc.inspect_num) as inspect_num ,sum(cc.passed_num) as passed_num,sum(cc.un_passed_num) as un_passed_num from ${inspectFinishReportTable} cc where cc.delete_flag = false GROUP BY cc.finish_main_id ), d as( select aa.finish_main_id,aa.inspect_type,string_agg(CAST(bb.staff_sign as TEXT),',') as inspectUserName from ${inspectFinishDispatcherTable} aa , ${staffTable} bb where aa.inspect_user_code = bb.primary_key GROUP BY aa.finish_main_id,aa.inspect_type ) select * from ( select aa.main_id,aa.buss_number,aa.create_time,aa.batch,aa.product_flag,aa.contract_code, aa.batch_num,aa.report_batch_no, aa.procedure_name,aa.model,aa.pcs_name,aa.product_or_part,aa.product_or_part_name, aa.operator_user_code,aa.task_num,aa.overdue_date,aa.status,aa.remark,aa.primary_key as primaryKeyValue,aa.enterprise_code,aa.primary_key, b.should_inspect_num,c.inspect_num, c.passed_num , c.un_passed_num , ROUND((c.passed_num/c.inspect_num) * 100,2) as passed_rate,d.inspectUserName,aa.check_items,d.inspect_type,e.status as approve_status from ${inspectFinishTable} aa LEFT JOIN b on aa.primary_key = b.finish_main_id LEFT JOIN c on aa.primary_key = c.finish_main_id LEFT JOIN d on aa.primary_key = d.finish_main_id left join ${approveTable} e on aa.primary_key = e.inspect_main_id where aa.delete_flag = false ) t where t.enterprise_code = #{enterpriseCode}
AND ( t.buss_number like concat('%', #{data.bussNumber}, '%') or t.batch like concat('%',#{data.bussNumber}, '%') )
AND t.product_or_part_name like concat('%',#{data.productOrPartName}, '%')
AND t.model like concat('%',#{data.model}, '%')
AND t.status = #{data.status}
and ${dynamicTableNameProxy.getXiHangPartQuery("t.product_or_part","xihang",data.partUnityNo)}
AND t.overdue_date >= #{data.beginDate}
AND t.overdue_date <= #{data.endDate}
AND t.operator_user_code = #{data.operatorUserCode}
AND exists ( select 1 from ${inspectFinishDispatcherTable} b where b.inspect_user_code IN
#{userCode}
and b.finish_main_id=t.primary_key)
AND t.passed_rate >= #{data.passRate}
and ${dynamicTableNameProxy.getProductPartSearchObj("t.product_or_part",data.searchName)}
order by t.create_time desc

WITH t as(
select cc.finish_main_id, batch_no,status, sum(cc.inspect_num) as inspect_num ,sum(cc.passed_num) as
passed_num,sum(cc.un_passed_num) as un_passed_num
from ${inspectFinishReportTable} cc
where cc.inspect_user = #{data.inspectUserCode[0]}
GROUP BY cc.finish_main_id,batch_no,status
)
select * from (
select b.buss_number,b.batch,b.product_flag,b.contract_code,
b.batch_num,b.report_batch_no,
b.procedure_name,b.model,b.pcs_name,b.product_or_part,b.product_or_part_name,
b.operator_user_code,b.task_num,a.finish_date as overdue_date,t.status,
a.remark,b.enterprise_code,b.create_time,b.check_items,b.model,b.pcs_name,
t.inspect_num,t.passed_num,t.un_passed_num,
ROUND((t.passed_num / t.inspect_num) * 100, 2) as passed_rate,
a.primary_key as primaryKeyValue,a.allocation_num as should_inspect_num,a.batch_no,a.finish_main_id as mainId
,e.status as approve_status
from ${inspectFinishDispatcherTable} a
LEFT JOIN ${inspectFinishTable} b on a.finish_main_id = b.primary_key
LEFT JOIN t on t.finish_main_id = a.finish_main_id and t.batch_no = a.batch_no
left join ${approveTable} e on b.primary_key = e.inspect_main_id
where a.inspect_user_code = #{data.inspectUserCode[0]}
and a.delete_flag = false
)tt
where tt.enterprise_code = #{enterpriseCode}

    AND (tt.buss_number like concat('%', #{data.bussNumber}, '%')
    or tt.batch like concat('%',#{data.bussNumber}, '%')
    )


    AND tt.product_or_part_name like concat('%',#{data.productOrPartName}, '%')


    AND tt.model like concat('%',#{data.model}, '%')




        AND (tt.status is null or tt.status = 30)


        AND tt.status = #{data.status}




    AND tt.overdue_date >= #{data.beginDate}



    AND tt.overdue_date <= #{data.endDate}



    and ${dynamicTableNameProxy.getXiHangPartQuery("tt.product_or_part","xihang",data.partUnityNo)}



    AND tt.operator_user_code = #{data.operatorUserCode}


    AND tt.passed_rate >= #{data.passRate}


and ${dynamicTableNameProxy.getProductPartSearchObj("tt.product_or_part",data.searchName)}

order by tt.create_time desc

